<div class="form-grid"><x-field name="name" label="Category name" :value="$record->name" :required="true" maxlength="100" placeholder="For example: Physics"/><x-field name="color" label="Category color" type="color" :value="$record->color" :required="true"/></div><x-field name="description" label="Description" type="textarea" :value="$record->description" rows="3" maxlength="2000" placeholder="What will learners explore in this subject?"/><x-toggle name="is_active" label="Active category" :value="$record->is_active" help="Inactive categories are hidden from the learner quiz catalog."/>
